const profile21=renderProfile;renderProfile=function(){profile21();const d=$('#profileEditor'),f=d.querySelector('form');if(!f)return;const fields=document.createElement('div');fields.innerHTML=`<label>微信号<input id="wxid21" maxlength="30" value="${escapeHtml(profile.wxid||'')}"></label><label>个性签名<input id="sign21" maxlength="100" value="${escapeHtml(profile.signature||'')}"></label><button type="button" class="secondary full" id="saveProfile21">保存微信号与签名</button>`;f.append(fields);$('#saveProfile21').onclick=()=>{try{const next={...profile,wxid:$('#wxid21').value.trim(),signature:$('#sign21').value.trim()};localSave('profile',next);profile=next;toast('资料已保存')}catch(e){toast(e.message)}}};
function feed21Open(owner=null){feed21Owner=owner;go('moments')}
renderMoments=function(){const owner=feed21Owner||'me',person=roles.find(r=>r.id===owner),posts=moments.filter(m=>!feed21Owner||m.author===feed21Owner).slice().sort((a,b)=>b.createdAt-a.createdAt),cover=mediaCache.get('cover21:'+owner);wx19Mount(feed21Owner?escapeHtml(feedName(owner)):'朋友圈',`<div class="cover21" id="cover21">${cover?`<img alt="朋友圈封面" src="${cover}">`:''}<button id="changeCover21">更换封面</button><div class="who21"><b>${escapeHtml(feedName(owner))}</b>${avatarHTML(owner==='me'?'profile':'role:'+owner,person?.emoji||'🎀')}</div></div>${feedActivityHTML()}<div class="posts21">${posts.map(m=>`<article class="post21" data-moment="${m.id}">${avatarHTML(m.author==='me'?'profile':'role:'+m.author,roles.find(r=>r.id===m.author)?.emoji||'🎀')}<div class="post21-body"><button class="name21" data-owner21="${escapeHtml(m.author)}">${escapeHtml(feedName(m.author))}</button><p>${escapeHtml(m.text)}</p>${mediaCache.has('moment:'+m.id)?`<img class="moment-photo" alt="动态配图" src="${mediaCache.get('moment:'+m.id)}">`:''}<div class="meta21"><span>${new Date(m.createdAt).toLocaleString('zh-CN')}${m.author==='me'?` <button data-delete21="${m.id}">删除</button>`:''}</span><button data-tools21="${m.id}" aria-label="点赞或评论">··</button></div><div class="feedback21">${m.likes?.length||m.liked?`<div class="likes21">♡ ${escapeHtml([...new Set([...(m.likes||[]),...(m.liked?['me']:[])])].map(feedName).join('，'))}</div>`:''}${(m.comments||[]).map(c=>{const parent=m.comments.find(x=>x.id===c.parentId);return `<button data-reply21="${m.id}|${c.id}"><b>${escapeHtml(feedName(c.author))}</b>${parent?' 回复 <b>'+escapeHtml(feedName(parent.author))+'</b>':''}：${escapeHtml(c.text)}</button>`}).join('')}</div></div></article>`).join('')||'<p class="soft-empty">还没有发过朋友圈</p>'}</div><form id="comment21" hidden><input name="text" required maxlength="1000" aria-label="朋友圈评论" placeholder="评论"><button>发送</button></form>`,!feed21Owner?`<button class="ib" id="post21" aria-label="发朋友圈">${wx19Icon('camera')}</button>`:'');$('#post21')?.addEventListener('click',createMoment);$('#feedActivity').onclick=openFeedNotices;$('#changeCover21').onclick=()=>cover21Pick(owner);screen.querySelectorAll('[data-owner21]').forEach(b=>b.onclick=()=>feed21Open(b.dataset.owner21));screen.querySelectorAll('[data-delete21]').forEach(b=>b.onclick=()=>deleteMoment(moments.find(m=>m.id===b.dataset.delete21)));screen.querySelectorAll('[data-tools21]').forEach(b=>b.onclick=()=>{screen.querySelector('.tools21')?.remove();const m=moments.find(x=>x.id===b.dataset.tools21),p=document.createElement('div');p.className='tools21';p.innerHTML='<button>♡ '+(m.liked?'取消':'赞')+'</button><button>评论</button>';p.children[0].onclick=()=>{const old=m.liked;try{m.liked=!old;saveSocial();renderMoments()}catch(e){m.liked=old;toast(e.message)}};p.children[1].onclick=()=>{p.remove();reply21(m)};b.parentElement.append(p)});screen.querySelectorAll('[data-reply21]').forEach(b=>b.onclick=()=>{const[id,c]=b.dataset.reply21.split('|');reply21(moments.find(x=>x.id===id),c)});$('#comment21').onsubmit=e=>{e.preventDefault();const text=e.target.text.value.trim();if(!text||!feed21Reply)return;try{const m=moments.find(x=>x.id===feed21Reply.id);if(!m)throw Error('动态已删除');const c={id:crypto.randomUUID(),author:'me',text,parentId:feed21Reply.parent||null,createdAt:Date.now()};commitComment(m,c);feed21Reply=null;renderMoments();queueInteractions(m,c)}catch(err){toast(err.message)}};notificationDots();nav21BackButton()};
function reply21(m,parent){feed21Reply={id:m.id,parent};const f=$('#comment21');f.hidden=false;f.text.placeholder=parent?'回复 '+feedName(m.comments.find(c=>c.id===parent).author)+'：':'评论';f.text.focus()}
