let auto21=localRead('auto21',{messages:0,feed:0,attempts:{},last:0}),auto21Busy=false;
function limit21(v,max){return Math.min(max,Math.max(0,Math.floor(Number(v)||0)))}
const api21=renderApi;renderApi=function(){api21();const section=document.createElement('section');section.className='auto21';section.innerHTML=`<h3>角色主动互动 · 每日额度</h3><form id="auto21Form"><label>主动私聊 · 所有角色合计 / 天<input name="messages" type="number" min="0" max="20" required value="${limit21(auto21.messages,20)}"></label><label>主动朋友圈 · 每角色 / 天<input name="feed" type="number" min="0" max="5" required value="${limit21(auto21.feed,5)}"></label><button class="primary full">保存每日额度</button></form><p class="api-note">0 为关闭。只在小手机打开且处于前台时运行；约每 15 分钟尝试一次，不补发离线期间的内容。额度按 API 尝试计数，失败也占用一次，防止反复调用。动态以相关聊天与记忆为依据，不公开私聊细节。点赞评论的额外 API 互动可在下方关闭。</p><label class="check"><input type="checkbox" id="social21" ${socialSettings.auto?'checked':''}>朋友圈点赞评论后自动互动（额外 API 调用）</label>`;screen.querySelector('.view').append(section);$('#auto21Form').onsubmit=e=>{e.preventDefault();try{const next={...auto21,messages:limit21(e.target.messages.value,20),feed:limit21(e.target.feed.value,5)};localSave('auto21',next);localSave('proactive',{...proactive,dailyMax:next.messages,enabled:next.messages>0,minutes:15});auto21=next;proactive={...proactive,dailyMax:next.messages,enabled:next.messages>0,minutes:15};toast('每日额度已保存，0 为关闭')}catch(err){toast(err.message)}};$('#social21').onchange=e=>{const old=socialSettings;try{socialSettings={...old,auto:e.target.checked};saveSocial()}catch(err){socialSettings=old;e.target.checked=old.auto;toast(err.message)}}};
function claim21(kind,id,max){const day=PalaisCore.dateKey(),k=day+':'+kind+':'+id,n=auto21.attempts[k]||0;if(n>=max||max<=0)return false;const next={...auto21,last:Date.now(),attempts:{...Object.fromEntries(Object.entries(auto21.attempts).filter(([k])=>k.startsWith(day))),[k]:n+1}};localSave('auto21',next);auto21=next;return true}
const proactive21=proactiveTick;proactiveTick=async function(force=false){if(!auto21.messages||auto21Busy||busy||memoryBusy||socialBusy||phoneLocked||document.hidden||!apiReady()||!proactiveDue({...proactive,enabled:true,dailyMax:auto21.messages},Date.now(),PalaisCore.dateKey())||isChatView())return false;auto21Busy=true;try{if(!claim21('message','all',limit21(auto21.messages,20)))return false;proactive={...proactive,enabled:true,dailyMax:limit21(auto21.messages,20)};return await proactive21(force)}finally{auto21Busy=false}};
async function generate21Moment(r,automatic){if(auto21Busy||busy||memoryBusy||socialBusy||!apiReady()){if(!automatic)toast('请连接 API，并等待当前回复结束');return false}if(automatic&&!claim21('feed',r.id,limit21(auto21.feed,5)))return false;auto21Busy=true;socialBusy=true;try{const history=histories[r.id]||[],text=await request({...config,key},[{role:'system',content:PalaisCore.systemPrompt(r,worldbook,history)+'\n'+memoryPrompt(r.id)+'\n'+sharedContext(r.id)+'\n'+relationshipPrompt(r.id)+'\n基于下面最近聊天与已有记忆，写20–100字朋友圈正文。只写你自己的感受或可公开的日常，不泄露私聊原文、用户秘密或敏感信息；没有依据时只写自己的此刻心情，不虚构与用户发生的事。'},{role:'user',content:JSON.stringify(history.slice(-12).map(m=>({role:m.role,content:m.content}))) }],400,AbortSignal.timeout(45000));if(phoneLocked)return false;commitMoment({id:crypto.randomUUID(),author:r.id,text,createdAt:Date.now(),liked:false,comments:[]});if(isMomentsView())renderMoments();if(!automatic)toast('角色动态已生成');return true}catch(e){toast('角色动态未完成：'+friendly(e));return false}finally{socialBusy=false;auto21Busy=false}}
setInterval(()=>{if(!auto21.feed||auto21Busy||busy||socialBusy||memoryBusy||phoneLocked||document.hidden||!apiReady()||Date.now()-auto21.last<900000)return;const day=PalaisCore.dateKey(),r=roles.find(r=>(auto21.attempts[day+':feed:'+r.id]||0)<limit21(auto21.feed,5));if(r)generate21Moment(r,true).catch(e=>toast(e.message))},30000);
